#include <stdio.h>
long long rev(long long n) {
    long long r = 0;
    while (n > 0) { r = r * 10 + (n % 10); n /= 10; }
    return r;
}
int main() {
    long long n; if (scanf("%lld", &n) != 1) return 0;
    if (n % 10 == 0) { printf("No\n"); return 0; }
    long long rn = rev(n);
    long long sq = n * n, sq_rev = rn * rn;
    if (rev(sq) == sq_rev) printf("Yes\n");
    else printf("No\n");
    return 0;
}

