code.Java:
import java.util.Scanner;
public class Main {
    static long rev(long n) {
        long r = 0;
        while (n > 0) { r = r * 10 + (n % 10); n /= 10; }
        return r;
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLong()) {
            long n = sc.nextLong();
            if (n % 10 == 0) { System.out.println("No"); return; }
            long rn = rev(n);
            if (rev(n * n) == rn * rn) System.out.println("Yes");
            else System.out.println("No");
        }
    }
}

